    tir:      { label: 'Tir',      color: '#ffb54a', w: .32 },
    pressing: { label: 'Pressing', color: '#ff5a4a', w: .24 },
    bascule:  { label: 'Bascule',  color: '#8fd0ff', w: .15, dash: [.2, .32] },
