      [['Ce qui a marché', af.good], ['Ce qu\'on travaille cette semaine', af.work], ['Thème du prochain entraînement', af.next]].forEach(([l, v]) => { if (lines(v).length) { P.label(l); P.bullets(lines(v)); writeLines(1); } else writeLines(3, l); });
