    const norm = e => { const r = L.cv.getBoundingClientRect(), b = L.box(); return [Math.max(0, Math.min(1, (e.clientX - r.left - b.x) / b.w)), Math.max(0, Math.min(1, (e.clientY - r.top - b.y) / b.h))]; };
