  const RE = { date: /^(\d{1,2})[\/.\- ](\d{1,2})[\/.\- ](\d{2}|\d{4})$|^(\d{4})-(\d{2})-(\d{2})/, licence: /^\d[\d ]{8,12}\d$/, time: /^\d{1,2}\s?[h:]\s?\d{0,2}$/i, score: /^\d{1,2}\s?[-–:]\s?\d{1,2}$/,
    phone: /^(\+33|0)\s?[1-9](?:[\s.-]?\d{2}){4}$/, email: /@.+\./, venue: /^(D|E|DOM|EXT|DOMICILE|EXTERIEUR)\.?$/i };
