      const again = bind(r); r._obSave = again; toast(`${Sport.cur().icon} Club de ${Sport.cur().label.toLowerCase()} : terrains, postes, catégories et scores changent (joueurs et matchs restent). Touche l'ancien sport pour revenir.`);
