    const vv = window.visualViewport, vh = window.innerHeight, vvH = vv ? vv.height : vh, vvTop = vv ? vv.offsetTop : 0;
    const keyboard = vh - vvH - vvTop > 80 || document.body.classList.contains('chat-kb');
